{
  "items": [
    {
      "name": "LiouvilleWith",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleWith",
      "kind": "definition",
      "type": "ℝ → ℝ → Prop"
    },
    {
      "name": "liouvilleWith_one",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleWith",
      "kind": "theorem",
      "type": "∀ (x : ℝ), LiouvilleWith 1 x"
    },
    {
      "name": "LiouvilleWith.rat_mul",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleWith",
      "kind": "theorem",
      "type": "∀ {p x : ℝ} {r : ℚ}, LiouvilleWith p x → r ≠ 0 → LiouvilleWith p (↑r * x)"
    },
    {
      "name": "LiouvilleWith.mono",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleWith",
      "kind": "theorem",
      "type": "∀ {p q x : ℝ}, LiouvilleWith p x → q ≤ p → LiouvilleWith q x"
    },
    {
      "name": "ae_not_liouvilleWith",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.Measure",
      "kind": "theorem",
      "type": "∀ᵐ (x : ℝ), ∀ p > 2, ¬LiouvilleWith p x"
    },
    {
      "name": "LiouvilleWith.mul_rat",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleWith",
      "kind": "theorem",
      "type": "∀ {p x : ℝ} {r : ℚ}, LiouvilleWith p x → r ≠ 0 → LiouvilleWith p (x * ↑r)"
    },
    {
      "name": "Liouville",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.Basic",
      "kind": "definition",
      "type": "ℝ → Prop"
    },
    {
      "name": "LiouvilleWith.exists_pos",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleWith",
      "kind": "theorem",
      "type": "∀ {p x : ℝ},\n  LiouvilleWith p x →\n    ∃ C, ∃ (_ : 0 < C), ∃ᶠ (n : ℕ) in Filter.atTop, 1 ≤ n ∧ ∃ m, x ≠ ↑m / ↑n ∧ |x - ↑m / ↑n| < C / ↑n ^ p"
    }
  ]
}
